CREATE TABLE `transaction_tai_xiu_sicbo` (
  `id` int NOT NULL AUTO_INCREMENT,
  `reference_id` bigint DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `user_name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `bet_value` bigint DEFAULT NULL,
  `bet_side` tinyint DEFAULT NULL,
  `total_prize` bigint DEFAULT NULL,
  `total_refund` bigint DEFAULT NULL,
  `total_exchange` bigint DEFAULT '0',
  `money_type` tinyint DEFAULT NULL,
  `timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `total_jackpot` bigint DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `reference_index` (`reference_id`) USING BTREE,
  KEY `user_name_index` (`user_name`) USING BTREE,
  KEY `timestamp_index` (`timestamp`) USING BTREE,
  KEY `money_type_index` (`money_type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
