CREATE DEFINER=`root`@`%` PROCEDURE `tx_get_jackpot`(IN `money_type` tinyint)
BEGIN
    SELECT user_name, total_prize as money
    FROM transaction_tai_xiu
    WHERE  transaction_tai_xiu.money_type = money_type AND transaction_tai_xiu.result = 1

    ORDER BY timestamp DESC
    LIMIT 0, 10;
END ;;
