CREATE DEFINER=`root`@`%` PROCEDURE `update_xd_boss`(IN p_sid NVARCHAR(100),
IN p_nn NVARCHAR(100),
IN p_fi BIGINT(20),
IN p_fee INT(11),
IN p_rv BIGINT(20),
IN p_type INT(11))
BEGIN 
